var a=`1292-pao-de-queijo`;var o=`world-1292`;var n=`BR`;var t=`south-america`;var r=8;var l=57;var s={en:`Pão de Queijo`,ua:`Пау ді кейжу`};var g={en:`Pão de Queijo is a dish from Brazil featuring whole cow milk, tapioca starch, parmigiano reggiano, mozzarella. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Пау ді кейжу, страва кухні країни Бразилія з такими основними складниками: цільне коров'яче молоко, тапіоковий крохмаль, парміджано реджано, моцарела. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`whole-cow-milk`,350,`ml`],[`water`,130,`ml`],[`canola-oil`,90,`ml`],[`table-salt`,8,`g`]]},{en:`Gradually pour the hot milk-oil mixture over tapioca starch; cool until safe to handle, then add eggs and cheese and knead gently.`,ua:`Поступово влийте гарячу молочно-олійну суміш до тапіокового крохмалю; остудіть до безпечної температури, додайте яйця та сир і обережно вимісіть.`,t:[`mixing`],m:13,i:[[`tapioca-starch`,510,`g`],[`parmigiano-reggiano`,230,`g`],[`mozzarella`,140,`g`],[`chicken-egg`,2,`pcs`]]},{en:`Divide and shape the prepared mixture or dough into even portions and arrange on a lined baking sheet or appropriate molds, leaving enough room for expansion.`,ua:`Розділіть і сформуйте підготовлене тісто чи масу на однакові порції, викладіть на деко з пергаментом або у форми, залишивши місце для збільшення об’єму.`,t:[`pre-shaping-dough`,`final-proofing`],m:12,i:[]},{en:`Bake the already topped dough in a fully preheated 230–250°C oven until the base is crisp and toppings are cooked.`,ua:`Випікайте готове тісто з начинкою в добре розігрітій духовці при 230–250°C до хрусткої основи та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:24,i:[]}];var h={slug:a,id:o,country:`BR`,region:t,servings:8,minutes:57,title:s,text:g,steps:d};export{n as country,h as default,o as id,l as minutes,t as region,r as servings,a as slug,d as steps,g as text,s as title};